#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

/// Ledgers a stake entry stays alive after each write (about 30 days at 5 seconds per ledger).
/// Persistent entries expire otherwise, which would silently drop a user's stake.
const TTL_THRESHOLD: u32 = 259_200;
const TTL_EXTEND_TO: u32 = 518_400;

#[contracttype]
pub enum DataKey {
    /// The staked token's contract address (instance storage).
    Token,
    /// Everything staked in total (instance storage).
    Total,
    /// One user's staked amount (persistent storage).
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

fn token_address(env: &Env) -> Address {
    env.storage().instance().get(&DataKey::Token).unwrap()
}

fn total(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn staked_of(env: &Env, user: &Address) -> i128 {
    env.storage()
        .persistent()
        .get(&DataKey::Staked(user.clone()))
        .unwrap_or(0)
}

fn set_staked(env: &Env, user: &Address, amount: i128) {
    let key = DataKey::Staked(user.clone());
    if amount == 0 {
        env.storage().persistent().remove(&key);
    } else {
        env.storage().persistent().set(&key, &amount);
        env.storage()
            .persistent()
            .extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
    }
}

fn set_total(env: &Env, amount: i128) {
    env.storage().instance().set(&DataKey::Total, &amount);
    env.storage()
        .instance()
        .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
}

#[contractimpl]
impl Staking {
    /// Runs once at deploy. `token` is the Stellar Asset Contract address of the staked asset
    /// (for XLM, the native asset's contract ID).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        set_total(&env, 0);
    }

    /// Moves `amount` of the token from `user` into this contract and credits `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }
        let this = env.current_contract_address();
        token::Client::new(&env, &token_address(&env)).transfer(&user, &this, &amount);

        set_staked(&env, &user, staked_of(&env, &user) + amount);
        set_total(&env, total(&env) + amount);
    }

    /// Returns `amount` of the token from this contract to `user`. Fails if `user` has less staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }
        let current = staked_of(&env, &user);
        if amount > current {
            panic_with_error!(&env, Error::InsufficientStake);
        }
        set_staked(&env, &user, current - amount);
        set_total(&env, total(&env) - amount);

        let this = env.current_contract_address();
        token::Client::new(&env, &token_address(&env)).transfer(&this, &user, &amount);
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        staked_of(&env, &user)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        total(&env)
    }
}

mod test;
EOF
