#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, Address, Env};

struct Setup<'a> {
    env: Env,
    staking: StakingClient<'a>,
    token: token::Client<'a>,
    token_admin: StellarAssetClient<'a>,
}

fn setup<'a>() -> Setup<'a> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let asset = env.register_stellar_asset_contract_v2(admin);
    let token_id = asset.address();
    let contract_id = env.register(Staking, (token_id.clone(),));

    Setup {
        staking: StakingClient::new(&env, &contract_id),
        token: token::Client::new(&env, &token_id),
        token_admin: StellarAssetClient::new(&env, &token_id),
        env,
    }
}

#[test]
fn starts_empty() {
    let s = setup();
    let user = Address::generate(&s.env);
    assert_eq!(s.staking.total_staked(), 0);
    assert_eq!(s.staking.staked(&user), 0);
}

#[test]
fn stake_moves_tokens_and_records_amount() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.token_admin.mint(&bob, &500);

    s.staking.stake(&alice, &600);
    s.staking.stake(&alice, &100);
    s.staking.stake(&bob, &500);

    assert_eq!(s.staking.staked(&alice), 700);
    assert_eq!(s.staking.staked(&bob), 500);
    assert_eq!(s.staking.total_staked(), 1_200);
    assert_eq!(s.token.balance(&alice), 300);
    assert_eq!(s.token.balance(&bob), 0);
    assert_eq!(s.token.balance(&s.staking.address), 1_200);
}

#[test]
fn unstake_returns_tokens_and_reduces_amount() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.staking.stake(&alice, &1_000);

    s.staking.unstake(&alice, &400);

    assert_eq!(s.staking.staked(&alice), 600);
    assert_eq!(s.staking.total_staked(), 600);
    assert_eq!(s.token.balance(&alice), 400);
    assert_eq!(s.token.balance(&s.staking.address), 600);

    // Unstaking everything leaves no stake behind.
    s.staking.unstake(&alice, &600);
    assert_eq!(s.staking.staked(&alice), 0);
    assert_eq!(s.staking.total_staked(), 0);
    assert_eq!(s.token.balance(&alice), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.staking.stake(&alice, &100);

    let result = s.staking.try_unstake(&alice, &101);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));

    // Nothing changed.
    assert_eq!(s.staking.staked(&alice), 100);
    assert_eq!(s.staking.total_staked(), 100);
    assert_eq!(s.token.balance(&alice), 900);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let result = s.staking.try_unstake(&alice, &1);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    assert_eq!(s.staking.try_stake(&alice, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.staking.try_stake(&alice, &-5), Err(Ok(Error::InvalidAmount)));
    s.staking.stake(&alice, &10);
    assert_eq!(s.staking.try_unstake(&alice, &0), Err(Ok(Error::InvalidAmount)));
}

#[test]
#[should_panic]
fn stake_requires_user_authorization() {
    let env = Env::default();
    let admin = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token_id,));
    let staking = StakingClient::new(&env, &contract_id);
    let alice = Address::generate(&env);
    // No authorization is mocked, so the user's require_auth must fail.
    staking.stake(&alice, &1);
}
