import { stakingContract } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type Outcome = { value: string } | { error: string };

/** Runs one read of the staking contract and turns the result, or the failure, into plain text. */
async function read(call: () => Promise<{ result: bigint }>): Promise<Outcome> {
  try {
    const { result } = await call();
    return { value: result.toString() };
  } catch (error) {
    // Some network errors arrive with an empty message; fall back to their text, and say where we called.
    const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
    return { error: `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})` };
  }
}

export default async function StakingPage({
  searchParams,
}: {
  searchParams: Promise<{ address?: string | string[] }>;
}) {
  // Reading searchParams makes this page render per request, so the contract is read when it is asked.
  const { address } = await searchParams;
  const total = await read(() => stakingContract().total_staked());
  const staked =
    address === undefined
      ? undefined
      : await read(() => stakingContract().staked({ user: String(address) }));

  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>

      <h2>Total staked</h2>
      {"value" in total ? (
        <p data-testid="total-staked">{total.value}</p>
      ) : (
        <p data-testid="total-staked-error">Could not read the total: {total.error}</p>
      )}

      <form method="get" action="/staking">
        <label>
          Address (G… or C…){" "}
          <input name="address" defaultValue={typeof address === "string" ? address : ""} size={60} />
        </label>{" "}
        <button type="submit">Show staked amount</button>
      </form>

      {staked !== undefined &&
        (Array.isArray(address) ? (
          <p data-testid="staked-error">Give one address, not several.</p>
        ) : "value" in staked ? (
          <p data-testid="staked-amount">{staked.value}</p>
        ) : (
          <p data-testid="staked-error">Could not read the staked amount: {staked.error}</p>
        ))}
    </main>
  );
}
